  ui_story_32160401_15_dialog_content = "Pareces saber un par de cosas sobre hacer cosas. ¿Qué tal si hablamos durante la comida?",
  ui_story_32160401_16_dialog_content = "Claro, he estado deseando escuchar tu opinión sobre la artesanía de Longzhou.",
