  ui_story_32160401_27_dialog_content = "¿Qué tal si arrojamos algo de luz sobre el \"Camino de los Artesanos\"?",
  ui_story_32160401_28_dialog_content = "Bueno, no estaba exactamente fuera de la tangente.",
  ui_story_32160401_29_dialog_content = "¿Quién dijo que las ollas y sartenes no podían ser inspiraciones?",
  ui_story_32160401_30_dialog_content = "Es como los varios artilugios que mencionamos antes...",
  ui_story_32160401_31_dialog_content = "El Toro Ardiente tiene forma de toro pero puede escupir fuego, una idea que obtuve de la llama de una olla caliente.",
  ui_story_32160401_32_dialog_content = "El Dragón Excavador tenía un cuerpo de escorpión con una cola para ayudar a las personas a cavar túneles, que provenía de la chimenea de la olla caliente.",
  ui_story_32160401_33_dialog_content = "El Harrier Torbellino podría aterrizar libremente incluso sin viento... El vapor del hot pot proporcionó la chispa.",
  ui_story_32160401_34_dialog_content = "¡Comer olla caliente es más útil de lo que piensas!",
