  ui_story_32160401_53_dialog_content = "¡Oye, esta estufa se ha calentado perfectamente, justo a tiempo!",
  ui_story_32160401_54_dialog_content = "Aquí está la comida que ustedes dos pidieron. ¡Disfruten!",
  ui_story_32160401_55_dialog_content = "¡Gracias!",
  ui_story_32160401_56_dialog_content = "Entonces, descubriste el \"Camino de los Artesanos\" a través de la olla caliente, ¿verdad?",
  ui_story_32160401_57_dialog_content = "¡Prueba este nuevo tipo de comida mientras está caliente!",
  ui_story_32160401_58_dialog_content = "Todavía me siento un poco confundido...",
  ui_story_32160401_59_dialog_content = "¿Por qué? ¿No es tu taza de té?",
  ui_story_32160401_60_dialog_content = "No, estoy repasando lo que dijiste en mi cabeza.",
  ui_story_32160401_61_dialog_content = "Te saltaste lo esencial, ¿verdad?",
  ui_story_32160401_62_dialog_content = "Si realmente pudieras percibir algo tan arcano en objetos comunes...",
  ui_story_32160401_63_dialog_content = "¿No habría muchos más artesanos que chefs, considerando la población de Longzhou?",
  ui_story_32160401_64_dialog_content = "Gag...",
  ui_story_32160401_65_dialog_content = "¡Jajaja...!",
  ui_story_32160401_66_dialog_content = "¡Deja de reír!",
  ui_story_32160401_67_dialog_content = "Sé lo que quisiste decir:",
  ui_story_32160401_68_dialog_content = "Los artesanos genios pueden obtener inspiración de cualquier cosa.",
  ui_story_32160401_69_dialog_content = "Estoy de acuerdo en que eso es cierto, pero no creo que sea la clave.",
  ui_story_32160401_70_dialog_content = "No, en realidad, es lo contrario directo.",
  ui_story_32160401_71_dialog_content = "En cuanto a los aparatos...",
  ui_story_32160401_72_dialog_content = "Solo aquellos que pueden inspirarse en algo más que dispositivos pueden convertirse en genios artesanos.",
  ui_story_32160401_73_dialog_content = "La verdadera sabiduría se encuentra en todas las cosas y en la naturaleza. Simplemente la aplicamos a los dispositivos.",
  ui_story_32160401_74_dialog_content = "Creo que lo entiendo, pero no estoy del todo seguro...",
  ui_story_32160401_75_dialog_content = "Hablando de naturaleza, ¿por qué tantos dispositivos tienen forma de animales?",
  ui_story_32160401_76_dialog_content = "Buena pregunta.",
  ui_story_32160401_77_dialog_content = "Qianyun, mi escuela de artesanía, cree:",
  ui_story_32160401_78_dialog_content = "No importa cuán complejo sea un dispositivo, no es nada comparado con la obra de la naturaleza.",
  ui_story_32160401_79_dialog_content = "Las formas y poderes de todas las cosas y cómo alcanzan la Lumina son resultados de milenios de supervivencia.",
  ui_story_32160401_80_dialog_content = "Es lo que más les conviene en este momento.",
  ui_story_32160401_81_dialog_content = "Entonces, Qianyun cree que imitar a los animales es imitar la naturaleza. Ese es el camino.",
  ui_story_32160401_82_dialog_content = "Por supuesto, no estás imitando cómo se ven, sino cómo funcionan.",
  ui_story_32160401_83_dialog_content = "Por ejemplo, construir algo que pueda trepar un árbol.",
  ui_story_32160401_84_dialog_content = "La clave no es hacer que parezca un mono, sino cómo funcionan las extremidades del mono.",
  ui_story_32160401_85_dialog_content = "Observa cómo se mueven, imita cómo actúan y finalmente obtén el resultado que deseas.",
  ui_story_32160401_86_dialog_content = "Ya veo... Parece que se trata de la teoría emergente del simulacro en ciertos laboratorios de Illumina.",
  ui_story_32160401_87_dialog_content = "Casi, aunque los artesanos de Longzhou han estado trabajando en ello durante miles de años.",
  ui_story_32160401_88_dialog_content = "Supongo que esa es una de las razones por las que los dos lados se están moviendo en direcciones diferentes.",
  ui_story_32160401_89_dialog_content = "Sí, ahora lo tengo mucho más claro.",
  ui_story_32160401_90_dialog_content = "¿Qué pasa con los dispositivos que no parecen animales? Como...",
  ui_story_32160401_91_dialog_content = "¿Como la Sombrilla Peculiar?",
  ui_story_32160401_92_dialog_content = "¡Sí!",
  ui_story_32160401_93_dialog_content = "Bueno, eso se debe a que los principios detrás de ello involucraban más que solo la escuela de diseño Qianyun...",
  ui_story_32160401_94_dialog_content = "Pero el camino de Dikun también.",
  ui_story_32160401_95_dialog_content = "Dikun es completamente diferente de Qianyun.",
  ui_story_32160401_96_dialog_content = "Creen que todo lo que crece de forma natural tiene defectos inherentes.",
  ui_story_32160401_97_dialog_content = "Las criaturas que nadan en el mar mueren cuando están fuera del agua. Las criaturas voladoras son frágiles. Las criaturas terrestres están ligadas a la tierra.",
  ui_story_32160401_98_dialog_content = "Solo las creaciones artificiales pueden estar libres de defectos. Solo nosotros podemos lograr la perfección.",
  ui_story_32160401_99_dialog_content = "Y como no tienes que lidiar con la perfección, debe ser inanimado.",
  ui_story_32160401_100_dialog_content = "Por eso no se ciñen a la vieja escuela de hacer que sus creaciones se parezcan a animales.",
  ui_story_32160401_101_dialog_content = "Entonces, tienden a crear principalmente trampas y dispositivos pasivos, agregando eventualmente pólvora a la mezcla.",
  ui_story_32160401_102_dialog_content = "No pareces estar en contra de Dikun, ¿verdad?",
  ui_story_32160401_103_dialog_content = "¿Por qué debería serlo? Esa es la sabiduría de todos los artesanos antes de que yo naciera también.",
  ui_story_32160401_104_dialog_content = "Me ayudó mucho, tanto como la olla caliente.",
  ui_story_32160401_105_dialog_content = "Si quieres saber, estoy en contra del statu quo actual entre las dos escuelas.",
  ui_story_32160401_106_dialog_content = "Discuten y pelean por siempre, alejándose cada vez más del arte.",
  ui_story_32160401_107_dialog_content = "Pero lo cierto es que ni siquiera están peleando por hacer mejores artilugios.",
  ui_story_32160401_108_dialog_content = "En cambio, quieren que la gente reconozca su superioridad, para que sus respectivos estudiantes se vean más dignos ante el rey.",
  ui_story_32160401_109_dialog_content = "Discusiones como esa son las que estancan las técnicas de construcción de aparatos en el Reino de Ye...",
  ui_story_32160401_110_dialog_content = "Por eso hice la sombrilla, simplemente para demostrar lo insignificante que es su disputa.",
  ui_story_32160401_111_dialog_content = "¿Por eso es tu favorito y lo llevas todos los días?",
  ui_story_32160401_112_dialog_content = "Así es. Tiene profesionales de ambas escuelas.",
  ui_story_32160401_113_dialog_content = "Imita la funcionalidad y es versátil. También es portátil, como ciertos dispositivos.",
  ui_story_32160401_114_dialog_content = "Esta sombrilla contiene libélulas de cobre y pájaros mecánicos, así como dardos y cuentas.",
  ui_story_32160401_115_dialog_content = "Activa y pasiva, ambas escuelas están en una. Puedes llamarlo mi obra maestra.",
  ui_story_32160401_116_dialog_content = "Interesante... Eso me provoca ganas de crear mi propio dispositivo.",
  ui_story_32160401_117_dialog_content = "Bueno, aunque reconozco tu talento e inteligencia...",
  ui_story_32160401_118_dialog_content = "No es tan fácil empezar de cero sin ninguna experiencia.",
  ui_story_32160401_119_option_content = "Enséñame, Xuan Ji! No... Maestro Xuan Ji!",
  ui_story_32160401_120_dialog_content = "¡Deja de halagarme! Bueno, puedo mostrarte algo simple. Considera eso como devolverte el favor.",
  ui_story_32160401_121_dialog_content = "Así que no pensarás que solo sirvo para las ollas calientes.",
  ui_story_32160401_122_option_content = "Está bien. ¿Cuál es un comienzo sencillo que puedo hacer?",
  ui_story_32160401_123_dialog_content = "Déjame pensar... Ah, lo tengo.",
  ui_story_32160401_124_dialog_content = "El relicario de corazón que hice antes. Comenzaremos con eso.",
  ui_story_32160401_125_dialog_content = "¿Relicario de corazón...?",
  ui_story_32160401_126_dialog_content = "Es un juguete rompecabezas del Reino Ye, con mecanismos de bloqueo entrecruzados. Es el dispositivo más sencillo.",
  ui_story_32160401_127_dialog_content = "Pero después de que lo resolví, esto ya no es algo que las personas normales puedan solucionar.",
  ui_story_32160401_128_dialog_content = "Entonces, ¿tengo que resolverlo?",
  ui_story_32160401_129_dialog_content = "Je, ¡relájate! Solo juega con ello.",
  ui_story_32160401_130_dialog_content = "Una vez que hayas jugado lo suficiente, la perspicacia comenzará a llegar...",
  ui_story_32160601_1_dialog_content = "¡Eso debería completar mis registros!",
  ui_story_32160601_2_dialog_content = "Gracias de nuevo por toda tu ayuda hoy, PlayerName.",
  ui_story_32160601_3_dialog_content = "No me di cuenta de que el Coloso podría darme una vista tan clara del cielo nocturno. Es de gran ayuda.",
  ui_story_32160601_4_dialog_content = "No lo menciones. Todo lo que hice fue ajustar un poco la proyección.",
  ui_story_32160601_5_dialog_content = "Además, también disfruto viéndolo.",
  ui_story_32160601_6_dialog_content = "¿Así que también te gusta mirar las estrellas?",
  ui_story_32160601_7_dialog_content = "¡Sip!",
  ui_story_32160601_8_dialog_content = "Cuando todavía estaba enterrado bajo tierra, Soroz me mostraba imágenes del mundo exterior.",
  ui_story_32160601_9_dialog_content = "Pero cuando finalmente vi las estrellas por mí misma, me di cuenta de lo lejos que realmente estaban...",
  ui_story_32160601_10_dialog_content = "Honestamente, me hizo sentir un poco triste.",
  ui_story_32160601_11_dialog_content = "Pero no hay forma de cambiar eso, ¿verdad? Entonces...",
  ui_story_32160601_12_dialog_content = "¿Estás desarrollando algún tipo de nueva máquina con toda esta investigación?",
  ui_story_32160601_13_dialog_content = "¡Eso es correcto! Después de todo, el Festival de Primavera está a la vuelta de la esquina.",
  ui_story_32160601_14_dialog_content = "¿Eh? ¿Qué tiene que ver con el Festival de Primavera?",
  ui_story_32160601_15_dialog_content = "¿Recuerdas que estudio bajo la secta Qianyun?",
  ui_story_32160601_16_dialog_content = "Si no estamos trabajando en algo urgente, se supone que discípulos como yo debemos visitar a nuestro maestro durante el Festival de Primavera.",
  ui_story_32160601_17_dialog_content = "De esa manera, podemos presumir, quiero decir, demostrar los frutos de nuestro trabajo de ese año.",
  ui_story_32160601_18_dialog_content = "Es por eso que cada vez que llega el festival, siento una creciente necesidad de trabajar en algo aún más grande.",
  ui_story_32160601_19_dialog_content = "Suena interesante.",
  ui_story_32160601_20_dialog_content = "Realmente me gustaría echar un vistazo a la secta Qianyun algún día.",
  ui_story_32160601_21_dialog_content = "El Reino Ye, donde la tecnología reina supremamente... ¡Debe ser un lugar realmente especial!",
  ui_story_32160601_22_dialog_content = "Espera, hablando del Festival de Primavera... ¿No vas a volver este año, verdad? ¿Está realmente bien?",
  ui_story_32160601_23_dialog_content = "¡No puedo hacer nada al respecto!",
  ui_story_32160601_24_dialog_content = "Me encantaría llevarte de vuelta y mostrarte los alrededores, pero es simplemente un viaje demasiado largo para llegar allí.",
  ui_story_32160601_25_dialog_content = "Es una pena.",
  ui_story_32160601_26_dialog_content = "Pero...",
  ui_story_32160601_27_dialog_content = "¿Pero?",
  ui_story_32160601_28_dialog_content = "¡Acabo de ser golpeado por la inspiración!",
  ui_story_32160601_29_dialog_content = "¡Te contaré todo sobre mis ideas muy pronto, lo prometo!",
  ui_story_32160601_30_dialog_content = "<color=#e8d9bb>Unos días después</color>",
  ui_story_32160601_31_dialog_content = "(La carta de Xuan Ji me dijo que viniera a este lugar.)",
  ui_story_32160601_32_dialog_content = "(Pero no veo nada alrededor aquí.)",
  ui_story_32160601_33_dialog_content = "Hacer clic—",
  ui_story_32160601_34_dialog_content = "¿Un cangrejo de fuego? ¡¿Qué está haciendo aquí?!",
  ui_story_32160601_35_dialog_content = "Clic, clic-",
  ui_story_32160601_36_dialog_content = "¿Me está indicando que vaya por allí?",
  ui_story_32160601_37_dialog_content = "¡Chirrido!",
  ui_story_32160601_38_dialog_content = "Está señalando con sus alas... ¿Es este camino, verdad?",
  ui_story_32160601_39_dialog_content = "Zumbido—",
  ui_story_32160601_40_dialog_content = "¿¡Dónde me llevas?!",
  ui_story_32160601_41_dialog_content = "E-Ey, no podemos simplemente irrumpir en las habitaciones de otras personas—",
  ui_story_32160601_42_dialog_content = "Espera, ¿es esto...?",
  ui_story_32160601_43_dialog_content = "¡Oh bueno, trajiste PlayerName!",
  ui_story_32160601_44_dialog_content = "¿Podrías decirme qué está pasando—",
  ui_story_32160601_45_dialog_content = "Xuan... Ji?",
  ui_story_32160601_46_dialog_content = "¿Qué pasa? ¿No me reconoces?",
  ui_story_32160601_47_dialog_content = "No, es solo que tu estilo es un poco diferente de lo habitual hoy.",
  ui_story_32160601_48_dialog_content = "Estas son las prendas tradicionales de los discípulos de la secta Qianyun. Cómodas y convenientes, ¿verdad?",
  ui_story_32160601_49_dialog_content = "Desafortunadamente, dado que todos usan el mismo atuendo exacto, nuestra ropa pierde un poco de su singularidad.",
  ui_story_32160601_50_dialog_content = "Creo que te quedan muy bien, Xuan Ji.",
  ui_story_32160601_51_dialog_content = "Casi se siente como si hubieras retrocedido en el tiempo a un momento antes de que nos conociéramos.",
  ui_story_32160601_52_dialog_content = "Jeje, si así es como te sientes, entonces tendré que usar este atuendo un poco más a menudo.",
  ui_story_32160601_53_dialog_content = "Espera, ¿eso significa que esta habitación también es...",
  ui_story_32160601_54_dialog_content = "¡Así es! ¡Es una réplica de mi taller en Qianyun!",
  ui_story_32160601_55_dialog_content = "¡Como este año no pude volver, pensé que podría traer una parte de ellos conmigo!",
  ui_story_32160601_56_dialog_content = "Eso tiene sentido, ¿verdad?",
  ui_story_32160601_57_dialog_content = "Seguro que sí... ¡Espera, no!",
  ui_story_32160601_58_dialog_content = "Esto puede parecerse a tu taller, ¡pero ninguno de tus compañeros discípulos está aquí!",
  ui_story_32160601_59_dialog_content = "¿Cómo se supone que debes mostrarles tu trabajo del año?",
  ui_story_32160601_60_dialog_content = "Oh, eso está bien para mí.",
  ui_story_32160601_61_dialog_content = "¿Por qué crees que es tan importante para mí compartir mi trabajo con los demás?",
  ui_story_32160601_62_dialog_content = "Bueno, las máquinas pueden ser realmente complicadas, por lo que unirse con otras personas es una excelente manera de aprender... ¿Verdad?",
  ui_story_32160601_63_dialog_content = "Correcto.",
  ui_story_32160601_64_dialog_content = "En otras palabras, mientras las personas puedan entenderse, también pueden aprender unas de otras sin importar la secta o el origen.",
  ui_story_32160601_65_dialog_content = "Además...",
  ui_story_32160601_66_dialog_content = "Este sombrilla en la que estoy trabajando no está destinada para ellos desde el principio.",
  ui_story_32160601_67_dialog_content = "Al tomar prestados algunos conceptos de la esfera armilar y simplificar sus estructuras, luego aplicar la información obtenida de las proyecciones estelares del Colossus...",
  ui_story_32160601_68_dialog_content = "Puedo producir los movimientos de las estrellas con este parasol.",
  ui_story_32160601_69_option_content = "¡E-Es hermoso!",
  ui_story_32160601_70_dialog_content = "Si no lo supiera, pensaría que es una obra de arte o algo así.",
  ui_story_32160601_71_dialog_content = "¡Tu elogio es muy apreciado!",
  ui_story_32160601_72_option_content = "Es más que simplemente hermoso.",
  ui_story_32160601_73_dialog_content = "... Lo siento, Xuan Ji.",
  ui_story_32160601_74_dialog_content = "¿Eh? ¿Por qué te estás disculpando?",
  ui_story_32160601_75_dialog_content = "Realmente quiero ofrecer mis elogios, pero no puedo pensar en las palabras correctas para decir.",
  ui_story_32160601_76_dialog_content = "La palabra \"hermoso\" ni siquiera comienza a describir la sensación de misterio y exploración del cielo nocturno...",
  ui_story_32160601_77_dialog_content = "¡Eso suena como una excelente manera de decirlo ya!",
  ui_story_32160601_78_dialog_content = "Ven aquí.",
  ui_story_32160601_79_dialog_content = "¿Ah?",
  ui_story_32160601_80_dialog_content = "La mejor manera de mirar las estrellas es tumbado de espaldas, ¿verdad?",
  ui_story_32160601_81_dialog_content = "¡N-No crees que esto es un poco demasiado cerca—",
  ui_story_32160601_82_dialog_content = "¿Puedes ver las siete estrellas de la Osa Mayor?",
  ui_story_32160601_83_dialog_content = "Tarda un año entero para que la manija complete un ciclo y vuelva a su posición original. Así es como sabemos cuando ha llegado la primavera.",
  ui_story_32160601_84_dialog_content = "En otras palabras, ¿el Festival de Primavera?",
  ui_story_32160601_85_dialog_content = "Así es. Un nuevo ciclo para un nuevo año.",
  ui_story_32160601_86_dialog_content = "Por eso las personas se ofrecen regalos en este día. Es su forma de agradecerse mutuamente por el pasado mientras esperan un futuro próspero.",
  ui_story_32160601_87_dialog_content = "He estado pensando durante mucho tiempo en qué darte.",
  ui_story_32160601_88_dialog_content = "Hasta ese día, dijiste que las estrellas estaban mucho más lejos de nosotros de lo que pensabas.",
  ui_story_32160601_89_dialog_content = "... Realmente no quise decir nada con eso, ya sabes.",
  ui_story_32160601_90_dialog_content = "¡Oh, discrepo!",
  ui_story_32160601_91_dialog_content = "Nuestro mito de la creación dice que cuando el caos apareció por primera vez, yin y yang se separaron, y las personas eran tanto ignorantes como incivilizadas.",
  ui_story_32160601_92_dialog_content = "Pero un día, un sabio comenzó a buscar orientación en las estrellas. Al medir y trazar sus movimientos, se determinaron el tiempo y el año, y todo cayó en orden.",
  ui_story_32160601_93_dialog_content = "Las estrellas nos guían de innumerables maneras, pero siempre están más allá de nuestro alcance.",
  ui_story_32160601_94_dialog_content = "No importa cuánto alcancemos, no importa cuán altos estemos, nunca podemos tocarlos.",
  ui_story_32160601_95_dialog_content = "Por esa razón, el cielo nocturno siempre ha sido un sueño de algún tipo para cada ser vivo.",
  ui_story_32160601_96_dialog_content = "Y hoy, finalmente he logrado acercar ese sueño un poco más a la realidad.",
  ui_story_32160601_97_dialog_content = "PlayerName. Mi querido amigo.",
  ui_story_32160601_98_dialog_content = "Me gustaría presentarte esta sombrilla, así como el sueño que representa.",
  ui_story_32160601_99_dialog_content = "Ya sea una tierra lejana, o las siempre distantes estrellas de arriba...",
  ui_story_32160601_100_dialog_content = "Espero que mi regalo te recuerde que nada está realmente fuera de tu alcance.",
  ui_story_32160601_101_dialog_content = "Si alguna vez me necesitas algún día, y me he ido a un lugar muy lejano de ti...",
  ui_story_32160601_102_dialog_content = "Mantén esta sombrilla a tu lado y siempre estaremos cerca el uno del otro, sin importar la distancia.",
  ui_story_32160601_103_dialog_content = "... Dios mío.",
  ui_story_32160601_104_dialog_content = "Solo desearía saber qué darte a cambio de algo tan precioso.",
  ui_story_32160601_105_dialog_content = "Jajaja, simplemente me alegra que te guste.",
  ui_story_32160601_106_dialog_content = "Puede que no sepa qué tipo de invenciones suelen crear tus compañeros discípulos.",
  ui_story_32160601_107_dialog_content = "Pero cualquiera estaría increíblemente orgulloso de esta sombrilla. Es una auténtica obra maestra.",
  ui_story_32160601_108_dialog_content = "Estoy de acuerdo contigo en eso.",
  ui_story_32160601_109_dialog_content = "Por cierto, estas estrellas...",
  ui_story_32160601_110_dialog_content = "(Las estrellas centelleaban justo al alcance, y el suave sonido de los engranajes girando llegó a nuestros oídos.)",
  ui_story_32160601_111_dialog_content = "(En ese espacio tranquilo, Xuan Ji me contó todas las historias de Longzhou sobre las estrellas.)",
  ui_story_32160601_112_dialog_content = "(Era tan tranquilo que antes de darme cuenta, empecé a sentir sueño.)",
  ui_story_32160601_113_dialog_content = "¿Te estás cansando? Adelante, duerme si quieres.",
  ui_story_32160601_114_dialog_content = "No te preocupes. No hay nada que temer cuando estás bajo mi sombrilla.",
  ui_story_32160601_115_dialog_content = "Ya sea que enfrentemos una tormenta aullante o una horda de espíritus malvados, siempre protegeré este pequeño rincón del mundo.",
  ui_story_32160601_116_dialog_content = "Después de todo, debajo de esta sombrilla...",
  ui_story_32160601_117_dialog_content = "Es mi logro más orgulloso en esta tierra."
}
return config
